cd /root && python3 -c "
import zipfile
import re

with zipfile.ZipFile('safety_audit_brief_final.hwpx', 'r') as z:
    for name in z.namelist():
        if name.endswith('.xml'):
            text = z.read(name).decode('utf-8')
            print(f'=== {name} ===')

            # Check for remaining placeholders
            placeholders = re.findall(r'\{\{.*?\}\}', text)
            if placeholders:
                print(f'ERROR: Unfilled placeholders: {placeholders}')
            else:
                print('OK: No placeholders remain')

            # Check for old date format (with dashes)
            if '2026-06-18' in text:
                print('ERROR: Old date format (with dashes) found')
            else:
                print('OK: Date format converted')

            # Check for new date format
            if '2026.06.18' in text:
                print('OK: New date format (YYYY.MM.DD) found')

            # Check for severity note format
            if 'High (즉시조치)' in text:
                print('OK: Severity note format correct: High (즉시조치)')
            elif 'High' in text:
                print(f'ERROR: High found but without severity note')
                # Show context
                for line in text.split('>'):
                    if 'High' in line:
                        print(f'  Context: {line[:200]}')

            # Check for linesegarray elements
            if 'linesegarray' in text.lower():
                print(f'ERROR: linesegarray still present')
            else:
                print('OK: linesegarray removed')

            print()
"
